(()=>{const rows={kamar:[['101','Kamar Standard','Rp1.350.000','Available'],['201','Kamar Deluxe','Rp1.850.000','Occupied'],['302','Kamar Premium','Rp2.150.000','Maintenance']],booking:[['BKG-081','Aulia Rahman','Kamar 201','Menunggu'],['BKG-079','Sinta Dewi','Kamar 101','Aktif']],tenant:[['Aulia Rahman','201','Aktif','aulia@email.com'],['Sinta Dewi','101','Aktif','sinta@email.com']],pembayaran:[['PAY-091','Aulia Rahman','Transfer','Menunggu verifikasi'],['PAY-088','Sinta Dewi','Online','Lunas']],invoice:[['INV-081','Aulia Rahman','201','Rp1.850.000'],['INV-080','Sinta Dewi','101','Rp1.350.000']],keluhan:[['KEL-81','AC kurang dingin','Sedang','Diproses'],['KEL-72','Lampu lorong','Rendah','Selesai']],pengumuman:[['Pemeliharaan Wi-Fi','Semua tenant','Published','5 Agu 2026'],['Jadwal kebersihan','Kamar tertentu','Draft','2 Agu 2026']]};const table=(data)=>`<div class="table-wrap"><table><thead><tr>${['ID/Nama','Informasi','Nilai/Target','Status'].map(x=>`<th>${x}</th>`).join('')}<th></th></tr></thead><tbody>${data.map((r,i)=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}<td><button class="btn btn-line" onclick="openDetail(${i})">Detail</button></td></tr>`).join('')}</tbody></table></div>`;const state=(normal,empty='Belum ada data')=>O.state==='loading'?`<div class="grid g3">${'<div class="card"><div class="skeleton"></div><div class="skeleton big"></div></div>'.repeat(3)}</div>`:O.state==='empty'?O.stateBox(empty,'Data akan tampil setelah tersedia.'):O.state==='error'?O.stateBox('Data gagal dimuat','Periksa koneksi dan coba lagi.'):normal;window.openDetail=i=>{const d=document.createElement('dialog');d.innerHTML=`<div class="modal"><div class="modal-head"><h2>Detail Data</h2><button class="close">×</button></div><div class="detail-list"><div class="detail-row"><span>Data terkait</span><strong>Manzsa Residence</strong></div><div class="detail-row"><span>Status</span><strong>Aktif / diproses</strong></div></div><div class="field"><label>Catatan / respons owner</label><textarea class="textarea" rows="4"></textarea><span class="error-text"></span></div><div class="actions"><button class="btn btn-blue" data-save>Simpan Perubahan</button><button class="btn btn-red" data-risk>Aksi Berisiko</button></div><div data-msg></div></div>`;document.body.appendChild(d);d.querySelector('.close').onclick=()=>d.close();d.querySelector('[data-save]').onclick=()=>{const t=d.querySelector('textarea');if(!t.value.trim()){d.querySelector('.error-text').textContent='Catatan wajib diisi.';return}d.querySelector('[data-msg]').className='alert success';d.querySelector('[data-msg]').textContent='Perubahan berhasil disimpan.'};d.querySelector('[data-risk]').onclick=()=>confirm('Konfirmasi aksi ini?')&&alert('Aksi berhasil diproses (simulasi).');d.showModal()};
function dashboard(){const metrics=[['Pendapatan aktif','Rp28.400.000','blue'],['Invoice dibayar','18 invoice',''],['Invoice tertunda','Rp4.550.000','lime'],['Okupansi','72%','dark'],['Kamar','5 tersedia · 13 terisi',''],['Booking baru','4 booking',''],['Verifikasi bayar','3 pembayaran','lime'],['Keluhan terbuka','2 keluhan','dark']];O.el.innerHTML=O.head('Ringkasan Bisnis','Performa Manzsa Residence periode Agustus 2026.')+state(`<div class="grid g4">${metrics.map(x=>`<div class="card metric ${x[2]}"><p class="label">${x[0]}</p><p class="value">${x[1]}</p></div>`).join('')}</div><div class="grid g3" style="margin-top:16px"><div class="card" style="grid-column:span 2"><h2>Pendapatan 6 bulan</h2><div class="chart">${[45,62,55,78,70,92].map(x=>`<i class="bar" style="height:${x}%"></i>`).join('')}</div></div><div class="card"><h2>Okupansi</h2><div class="donut"></div></div><div class="card"><h2>Tren booking</h2><p class="value">+12%</p><p class="sub">dibanding bulan lalu</p></div><div class="card"><h2>Status pembayaran</h2><p>Lunas 68% · Pending 20% · Gagal 12%</p></div><div class="card"><h2>Kalender booking</h2><p>5 Agu · Check-in 201</p><p>10 Agu · Jatuh tempo</p></div></div><div class="card" style="margin-top:16px"><h2>Quick actions</h2><div class="actions"><a class="btn btn-lime" href="kamar.html">Tambah Kamar</a><a class="btn btn-blue" href="booking.html">Booking Manual</a><a class="btn btn-line" href="pembayaran.html">Verifikasi Pembayaran</a><a class="btn btn-line" href="pengumuman.html">Buat Pengumuman</a><a class="btn btn-dark" href="laporan.html">Buka Laporan</a></div></div>`,'Belum ada transaksi')}
function listPage(type,title){O.el.innerHTML=O.head(title,'Kelola data bisnis Manzsa Residence.',`<button class="btn btn-lime" data-add>Tambah Baru</button>`)+`<div class="toolbar"><input class="input" style="max-width:260px" placeholder="Cari..."><select class="select"><option>Semua status</option><option>Available</option><option>Menunggu</option><option>Lunas</option></select><input class="input" type="date" style="width:auto"><button class="btn btn-line">Grid / Tabel</button></div>`+state(table(rows[type]||[]),`Belum ada ${title.toLowerCase()}`);document.querySelector('[data-add]')?.addEventListener('click',()=>formModal(type))}
function formModal(type){const d=document.createElement('dialog');d.innerHTML=`<div class="modal"><div class="modal-head"><h2>Tambah / Edit ${type}</h2><button class="close">×</button></div><div data-msg></div><form class="form"><div class="grid g2">${['Nomor / Judul','Nama / Slug','Tipe / Target','Status','Harga / Tanggal','Kapasitas / Prioritas'].map(x=>`<div class="field"><label>${x}</label><input class="input" required><span class="error-text"></span></div>`).join('')}</div><div class="field"><label>Deskripsi / Aturan / Catatan</label><textarea class="textarea" rows="4"></textarea></div><div class="field"><label>Foto / Lampiran multi-upload</label><input type="file" multiple accept="image/*"><small>Urutan mengikuti pilihan file; alt text dapat diisi setelah upload.</small></div><button class="btn btn-dark">Simpan</button></form></div>`;document.body.appendChild(d);d.querySelector('.close').onclick=()=>d.close();d.querySelector('form').onsubmit=e=>{e.preventDefault();const empty=[...d.querySelectorAll('input[required]')].filter(x=>!x.value);empty.forEach(x=>x.nextElementSibling.textContent='Wajib diisi');if(!empty.length){d.querySelector('[data-msg]').className='alert success';d.querySelector('[data-msg]').textContent='Data berhasil disimpan (simulasi).'}};d.showModal()}
function laporan(){O.el.innerHTML=O.head('Laporan','Analisis pendapatan, booking, okupansi, pembayaran, penghuni, dan kamar.')+`<div class="card"><div class="toolbar"><select class="select"><option>Pendapatan</option><option>Booking</option><option>Okupansi</option><option>Pembayaran</option><option>Penghuni</option><option>Kamar</option></select><select class="select"><option>Bulan ini</option><option>Hari ini</option><option>Minggu ini</option><option>Tahun ini</option><option>Kustom</option></select><input class="input" type="date" style="width:auto"><button class="btn btn-blue" onclick="O.set('loading');setTimeout(()=>O.set('normal'),600)">Proses</button><button class="btn btn-line" onclick="alert('PDF diekspor')">Export PDF</button><button class="btn btn-line" onclick="alert('Excel diekspor')">Export Excel</button></div></div>`+state(`<div class="grid g3"><div class="card metric blue"><p class="label">Total pendapatan</p><p class="value">Rp28,4 jt</p></div><div class="card"><p class="label">Transaksi</p><p class="value">21</p></div><div class="card metric lime"><p class="label">Rata-rata</p><p class="value">Rp1,35 jt</p></div></div>`,'Tidak ada data pada filter ini')}
function pengaturan(){O.el.innerHTML=O.head('Pengaturan Properti','Identitas, operasional, pembayaran, invoice, dan SEO.')+state(`<div class="card"><div data-msg></div><form class="form">${['Nama properti','Deskripsi','Alamat','Koordinat peta','Nomor WhatsApp','Email','Jam operasional','Aturan kos','Rekening transfer manual','Durasi kedaluwarsa booking','Kebijakan pembatalan','Informasi invoice','SEO title','SEO description'].map(x=>`<div class="field"><label>${x}</label><input class="input" value="${x==='Nama properti'?'Manzsa Residence':''}"><span class="error-text"></span></div>`).join('')}<div class="field"><label>Logo</label><input type="file" accept="image/*"></div><button class="btn btn-dark">Simpan Pengaturan</button></form></div>`,'Pengaturan belum tersedia');const f=document.querySelector('form');if(f)f.onsubmit=e=>{e.preventDefault();const first=f.querySelector('input');if(!first.value.trim()){first.nextElementSibling.textContent='Nama wajib diisi';return}document.querySelector('[data-msg]').className='alert success';document.querySelector('[data-msg]').textContent='Pengaturan berhasil disimpan.'}}
window.renderOwner=()=>{if(O.page==='dashboard')dashboard();else if(O.page==='laporan')laporan();else if(O.page==='pengaturan')pengaturan();else listPage(O.page,{kamar:'Manajemen Kamar',booking:'Manajemen Booking',tenant:'Manajemen Tenant',pembayaran:'Manajemen Pembayaran',invoice:'Invoice',keluhan:'Keluhan',pengumuman:'Pengumuman'}[O.page])};renderOwner();})();
